from .lexer import split_assignment

def parse_value(raw: str):
    return raw

def parse_config(text: str) -> dict:
    result = {}
    for number, line in enumerate(text.splitlines(), 1):
        if not line:
            continue
        key, raw = split_assignment(line, number)
        result[key] = parse_value(raw)
    return result

