import unittest
from config_lang import parse_config, render_config

class ConfigTests(unittest.TestCase):
    def test_types_comments_and_whitespace(self):
        text = '# demo\nname = \"worker a\"\nenabled = true\nretries = -3\ntags = [\"api\", 2, false]\n'
        self.assertEqual(parse_config(text), {'name':'worker a','enabled':True,'retries':-3,'tags':['api',2,False]})
    def test_round_trip_is_stable(self):
        value = {'z': [1, 'two', True], 'a': 'hello'}
        rendered = render_config(value)
        self.assertEqual(rendered.splitlines()[0].split('=',1)[0].strip(), 'a')
        self.assertEqual(parse_config(rendered), value)
    def test_rejects_bad_input_with_line(self):
        for text, line in [('ok = 1\nok = 2', '2'), ('bad-key = 1', '1'), ('x = maybe', '1'), ('x = [1,]', '1')]:
            with self.subTest(text=text):
                with self.assertRaisesRegex(ValueError, line): parse_config(text)
